package com.bank.txn;

// A node in a linked-transaction chain, carrying an amount.
public class TxnNode {
    private final int amount;
    private TxnNode left;
    private TxnNode right;

    public TxnNode(int amount) {
        this.amount = amount;
    }

    public int getAmount() { return amount; }
    public TxnNode getLeft() { return left; }
    public TxnNode getRight() { return right; }
    public void setLeft(TxnNode left) { this.left = left; }
    public void setRight(TxnNode right) { this.right = right; }
}
