package com.bank.txn;

import java.util.HashMap;
import java.util.Map;
import java.util.logging.Logger;

// Path Sum (root-to-leaf) and Path Sum III (all downward paths).
public class PathSumService {

    private static final Logger log = Logger.getLogger(PathSumService.class.getName());

    // ----- Path Sum: any root-to-leaf chain equals target? -----
    public boolean hasPathSum(TxnNode node, int target) {
        if (node == null) {
            return false;
        }
        int remaining = target - node.getAmount();
        if (node.getLeft() == null && node.getRight() == null) {
            return remaining == 0; // leaf: did we hit the target exactly?
        }
        return hasPathSum(node.getLeft(), remaining)
                || hasPathSum(node.getRight(), remaining);
    }

    // ----- Path Sum III: count all downward paths summing to target -----
    public int countPaths(TxnNode root, int target) {
        Map<Long, Integer> prefixCounts = new HashMap<>();
        prefixCounts.put(0L, 1); // empty prefix → enables root-starting paths
        return count(root, 0L, target, prefixCounts);
    }

    private int count(TxnNode node, long runningSum, int target,
                      Map<Long, Integer> prefixCounts) {
        if (node == null) {
            return 0;
        }
        runningSum += node.getAmount();
        // Paths ending here: how many ancestor prefixes = runningSum - target.
        int paths = prefixCounts.getOrDefault(runningSum - target, 0);

        // Record this prefix for descendants.
        prefixCounts.merge(runningSum, 1, Integer::sum);
        paths += count(node.getLeft(), runningSum, target, prefixCounts);
        paths += count(node.getRight(), runningSum, target, prefixCounts);
        // Backtrack: remove this prefix so siblings do not double-count.
        prefixCounts.merge(runningSum, -1, Integer::sum);

        return paths;
    }

    public void analyze(TxnNode root, int target) {
        boolean full = hasPathSum(root, target);
        int all = countPaths(root, target);
        log.info(() -> "Full origin-to-terminal chain summing to " + target + "? " + full);
        log.info(() -> "Total downward sub-chains summing to " + target + " = " + all);
    }
}
