package com.bank.txn;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

public class PathSumDemo {

    private static final Logger log = Logger.getLogger(PathSumDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) {
            root.removeHandler(h);
        }
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — Transaction Chain Path Sums");

        //            10
        //          /    \
        //         5      -3
        //        / \       \
        //       3   2       11
        //      / \   \
        //     3  -2   1
        // target = 8
        TxnNode root = new TxnNode(10);
        root.setLeft(new TxnNode(5));
        root.setRight(new TxnNode(-3));
        root.getLeft().setLeft(new TxnNode(3));
        root.getLeft().setRight(new TxnNode(2));
        root.getRight().setRight(new TxnNode(11));
        root.getLeft().getLeft().setLeft(new TxnNode(3));
        root.getLeft().getLeft().setRight(new TxnNode(-2));
        root.getLeft().getRight().setRight(new TxnNode(1));

        new PathSumService().analyze(root, 8);
    }
}
